policies.inbound:




    {{apim-app-client-id}}
    api://{{apim-app-client-id}}








  https://login.microsoftonline.com/{{tenant-id}}/oauth2/v2.0/token
  POST

    application/x-www-form-urlencoded

  @{
    return "grant_type=urn:ietf:params:oauth:grant-type:jwt-bearer"
      + "&client_id={{apim-app-client-id}}"
      + "&client_assertion_type=urn:ietf:params:oauth:client-assertion-type:jwt-bearer"
      + "&client_assertion=" + System.Net.WebUtility.UrlEncode((string)context.Variables["MiAssertionToken"])
      + "&assertion=" + System.Net.WebUtility.UrlEncode((string)context.Variables["UserToken"])
      + "&scope=" + System.Net.WebUtility.UrlEncode("{{ado-scope}} openid profile")
      + "&requested_token_use=on_behalf_of";
  }




    <set-variable name="OboError" value="@{
      var body = ((IResponse)context.Variables["OboResponse"]).Body.As(preserveContent: true);
      try {
        var json = Newtonsoft.Json.Linq.JObject.Parse(body);
        return json["error"]?.ToString() ?? "unknown_error";
      } catch { return "unknown_error"; }
    }" />





            application/json

          @{
            var gatewayUrl = context.Request.OriginalUrl.Scheme + "://" + context.Request.OriginalUrl.Host;
            return Newtonsoft.Json.JsonConvert.SerializeObject(new {
              error = "consent_required",
              error_description = "User consent is required for Azure DevOps access. Visit the consent_uri to grant access.",
              consent_uri = gatewayUrl + "/authorize"
            });
          }






            application/json

          @{
            var body = ((IResponse)context.Variables["OboResponse"]).Body.As(preserveContent: true);
            return Newtonsoft.Json.JsonConvert.SerializeObject(new {
              error = "token_exchange_failed",
              error_description = body
            });
          }






<set-variable name="AdoToken" value="@{
  var body = ((IResponse)context.Variables["OboResponse"]).Body.As(preserveContent: true);
  var json = Newtonsoft.Json.Linq.JObject.Parse(body);
  return json["access_token"]?.ToString() ?? string.Empty;
}" />

  @("Bearer " + (string)context.Variables["AdoToken"])

set-header.value:
@{
            var gatewayUrl = context.Request.OriginalUrl.Scheme + "://" + context.Request.OriginalUrl.Host;
            return "Bearer resource_metadata=\"" + gatewayUrl + "/well-known/oauth-protected-resource\"";
          }
